<?php
declare(strict_types=1);
require_once __DIR__ . '/business/config/role_portal_auth.php';
$pdo=role_portal_db();$user=role_portal_require($pdo,'coach');$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];
$metrics=['leads'=>0,'customers'=>0,'new_leads'=>0,'followups'=>0];
try{
    if(business_table_exists($pdo,'crm_leads')){$s=$pdo->prepare("SELECT COUNT(*) total,SUM(stage='new') new_count FROM crm_leads WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$r=$s->fetch()?:[];$metrics['leads']=(int)($r['total']??0);$metrics['new_leads']=(int)($r['new_count']??0);}
    if(business_table_exists($pdo,'customers')){$s=$pdo->prepare("SELECT COUNT(*) FROM customers WHERE organization_id=? AND status='active'");$s->execute([$orgId]);$metrics['customers']=(int)$s->fetchColumn();}
    if(business_table_exists($pdo,'crm_followup_tasks')){$s=$pdo->prepare("SELECT COUNT(*) FROM crm_followup_tasks WHERE organization_id=? AND status IN ('pending','open')");$s->execute([$orgId]);$metrics['followups']=(int)$s->fetchColumn();}
}catch(Throwable){}
